item.command:
/bin/bash -lc "python3 - <<'PY'
import urllib.request,concurrent.futures,json,pathlib,hashlib
urls={'megadock_readme.md':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/README.md','megadock_licence.txt':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/LICENSE'}
def fetch(item):
 name,url=item
 try:
  with urllib.request.urlopen(url,timeout=15) as r:b=r.read()
  pathlib.Path('intake',name).write_bytes(b)
  return {'url':url,'status':'retrieved','sha256':hashlib.sha256(b).hexdigest()}
 except Exception as e:return {'url':url,'status':'unavailable','reason':str(e)}
receipts=list(concurrent.futures.ThreadPoolExecutor(2).map(fetch,urls.items()))
brief=pathlib.Path('intake/brief.md').read_text()
import re
pdbs=sorted(set(re.findall(r'https://pinderdata.org/2024-02/pdbs/["'^ |'"\\n]+',brief[:brief.index('### Recorded data and source locations')])))
def head(url):
 try:
  with urllib.request.urlopen(urllib.request.Request(url,method='HEAD'),timeout=15) as r:return {'url':url,'status':r.status,'content_length':r.headers.get('Content-Length'),'scope':'reachability only; no payload hash verification'}
 except Exception as e:return {'url':url,'status':'unknown','reason':str(e)}
receipts+=list(concurrent.futures.ThreadPoolExecutor(8).map(head,pdbs))
pathlib.Path('intake/source_checks.json').write_text(json.dumps(receipts,indent=2)+'\\n')
print(json.dumps(receipts,indent=2))
PY"

